async function ssvPhotoSave(src){try{const response=await fetch(src,{credentials:'include'});if(!response.ok)throw Error('دریافت تصویر ناموفق بود');const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='بازدید-سرویس-مدارس.'+(blob.type==='image/png'?'png':'jpg');document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}catch(e){alert(e.message||'ذخیره تصویر ممکن نشد.')}}
