function isCertificateViolation(v){
 const s=String(v??'').replace(/[\u200c\u200f]/g,' ').replace(/\s+/g,' ').trim();
 return /گواهی\s*صلاحیت|صلاحیت\s*معتبر|داشتن\s*یا\s*نداشتن/.test(s);
}

function ssvModal(title,html,onSave){const m=document.createElement('div');m.className='ssv-form-modal';m.innerHTML='<div class="ssv-form-box"><div class="ssv-form-head"><b>'+esc(title)+'</b><button type="button" class="ssv-close">بستن</button></div><div class="ssv-form-body">'+html+'</div><div class="ssv-form-foot"><button type="button" class="ssv-cancel alt">انصراف</button><button type="button" class="ssv-submit">ذخیره</button></div></div>';document.body.appendChild(m);const close=()=>m.remove();m.querySelector('.ssv-close').onclick=close;m.querySelector('.ssv-cancel').onclick=close;m.querySelector('.ssv-submit').onclick=async()=>{const ok=await onSave(m);if(ok!==false)close()};return m}
