function districtKey(v){
 const s=String(v??'').trim()
  .replace(/[٠-٩]/g,ch=>'0123456789'['٠١٢٣٤٥٦٧٨٩'.indexOf(ch)])
  .replace(/[۰-۹]/g,ch=>'0123456789'['۰۱۲۳۴۵۶۷۸۹'.indexOf(ch)])
  .replace(/^(ناحیه|منطقه)[\\s\\u200c\\u200f]*/,'')
  .replace(/[\\s\\u200c\\u200f]+/g,'');
 return s;
}
