const mapEl=container.querySelector('#ssv-school-map');if(!window.L){mapEl.innerHTML='<div class="ssv-map-empty">کتابخانه نقشه در دسترس نیست.</div>';return}
const map=L.map(mapEl,{zoomControl:true,attributionControl:true}).setView([36.2972,59.6067],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);S.schoolMap=map;
