(rows||[]).forEach(r=>{const lat=Number(r.latitude),lng=Number(r.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lng))return;count++;bounds.push([lat,lng]);const marker=L.marker([lat,lng]).addTo(map);const company=esc(r.company_names||'نامشخص');marker.bindPopup('<div dir="rtl" style="font-family:Vazirmatn,Tahoma;min-width:220px"><b>'+esc(r.name||'مدرسه')+'</b><div>ناحیه: '+esc(r.educational_district||'نامشخص')+'</div><div>نوع: '+esc(r.gender||'نامشخص')+'</div><div>شرکت مجری: '+company+'</div><div>آدرس: '+esc(r.address||'ثبت نشده')+'</div></div>');const btn=document.createElement('button');btn.type='button';btn.className='ssv-school-pick';btn.innerHTML='<b>'+esc(r.name||'مدرسه')+'</b><div style="font-size:11px;color:#667085;margin-top:3px">'+esc(r.educational_district||'')+' • '+company+'</div>';btn.onclick=()=>{map.setView([lat,lng],17);marker.openPopup()};list.appendChild(btn)});
