function ssvFa(n){return new Intl.NumberFormat('fa-IR').format(Number(n)||0)}
function ssvBars(items,limit=8){const a=(items||[]).slice(0,limit);if(!a.length)return '<div class="ssv-empty-chart">داده‌ای برای نمایش وجود ندارد.</div>';const mx=Math.max(1,...a.map(x=>Number(x.n)||0));return '<div class="ssv-bars">'+a.map(x=>'<div class="ssv-bar-row"><div class="ssv-bar-label" title="'+esc(x.label||'نامشخص')+'">'+esc(x.label||'نامشخص')+'</div><div class="ssv-bar-track"><div class="ssv-bar-fill" style="width:'+Math.max(2,Math.round((Number(x.n)||0)/mx*100))+'%"></div></div><div class="ssv-bar-value">'+ssvFa(x.n)+'</div></div>').join('')+'</div>'}
function ssvTrend(items){const a=items||[];if(!a.length)return '<div class="ssv-empty-chart">هنوز سابقه‌ای ثبت نشده است.</div>';const mx=Math.max(1,...a.map(x=>Number(x.n)||0));const fmt=new Intl.DateTimeFormat('fa-IR-u-ca-persian',{day:'numeric',month:'long',year:'numeric'});const dayFmt=new Intl.DateTimeFormat('fa-IR-u-ca-persian',{day:'numeric'});return '<div class="ssv-trend">'+a.map(x=>{const d=/^\d{4}-\d{2}-\d{2}$/.test(String(x.ym||''))?new Date(String(x.ym)+'T12:00:00'):null;const label=d?dayFmt.format(d):String(x.ym||'');const full=d?fmt.format(d):label;return '<div class="ssv-trend-col" title="'+esc(full)+'"><b>'+ssvFa(x.n)+'</b><div class="ssv-trend-bar" style="height:'+Math.max(3,Math.round((Number(x.n)||0)/mx*135))+'px"></div><small>'+esc(label)+'</small></div>'}).join('')+'</div>'}
function ssvDonut(items){const a=(items||[]).slice(0,6);if(!a.length)return '<div class="ssv-empty-chart">داده‌ای برای نمایش وجود ندارد.</div>';const total=Math.max(1,a.reduce((s,x)=>s+(Number(x.n)||0),0));const colors=['#0d7a5f','#126e8f','#d99a16','#b54b68','#6f56a8','#718096'];let start=0;const stops=a.map((x,i)=>{const end=start+(Number(x.n)||0)/total*360;const z=colors[i%colors.length]+' '+start+'deg '+end+'deg';start=end;return z}).join(',');return '<div class="ssv-donut-wrap"><div class="ssv-donut" style="background:conic-gradient('+stops+')"></div><div class="ssv-legend">'+a.map((x,i)=>'<div><i style="background:'+colors[i%colors.length]+'"></i>'+esc(x.label||'نامشخص')+' <b>'+ssvFa(x.n)+'</b></div>').join('')+'</div></div>'}
